import React from "react";
import bacgroundVideo from "./back.mp4";

function Section1() {
  return (
    <div>
      <video
        className=" w-full h-screen object-cover absolute top-0 z-[-10]"      
      src={bacgroundVideo} loop muted autoPlay></video>
      <div className=" flex bg-black absolute ">

      <h1 className="  text-6xl">Explore The Wonder Of Solar System</h1>
      </div>
    </div>
  );
}

export default Section1;
